'use strict';
const KEY='builders-reading-atlas-v1';
let books=[], index=new Map(), records={}, page='home', shown=24, currentBook=null, lastFocus=null;
let filters={domain:'all',kind:'all',category:'all',stage:'all',difficulty:'all',q:'',sort:'curated',view:'grid'};
let shelfFilter='all';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’‘]/g,"'").replace(/[–—]/g,'-').toLowerCase();
const slug=s=>norm(s).replace(/[^a-z0-9]+/g,'-');
const levels=['','Easy entry','Accessible','Focused reading','Technical / dense','Advanced reference'];
const statusNames={want:'Want to read',reading:'Reading',finished:'Finished'};
const palettes=[['#304c47','#f1e8cc'],['#b4593c','#fff0d8'],['#d8c890','#283c33'],['#3c5269','#f4e9d3'],['#8d4b50','#f7e5cc'],['#9aa58b','#243b34'],['#c8ad88','#2e423b'],['#4f5a40','#f2e7ca']];
const paths=[
 {id:'first',name:'Your first twelve',caption:'A small shelf. A big beginning.',desc:'Six grounded books and six imagined worlds. Alternate between how things work and what they might make possible. These are invitations, not prerequisites.',titles:['The Knowledge','The Player of Games','Structures','The Martian','The Perfectionists','All Systems Red','Making Things Move','The Long Way to a Small, Angry Planet','A Mind for Numbers','Project Hail Mary','Thinking in Systems','A Psalm for the Wild-Built'],project:'Keep two notes: one thing you can explain, and one question you want to test.'},
 {id:'factory',name:'The factory that builds the future',caption:'Precision → production → possibility',desc:'Follow the hidden industrial chain behind a capable machine. Pair the grand futures with the tools, materials, supply chains, and decisions that make them possible.',titles:['How to Invent Everything','The Perfectionists','Material World','The Goal','Chip War','The Knowledge','Excession','The Dispossessed'],project:'Draw the supply chain behind one ordinary mechanism. Circle everything your own workshop could not yet make.'},
 {id:'flight',name:'From algebra to flight',caption:'Build the language. Feel the physics.',desc:'Move from mathematical confidence to mechanical intuition and flight. The later technical books are a shelf to grow into; do not rush them before the prerequisites.',titles:['A Mind for Numbers','College Algebra 2e','Precalculus','The Simple Science of Flight','Structures','Introduction to Flight','Fundamentals of Aerodynamics','The Martian','Rendezvous with Rama'],project:'Explain one force, one load path, and one assumption behind a machine you can see.'},
 {id:'habitats',name:'Somewhere to live',caption:'Habitats are systems—and societies.',desc:'Put large settlement visions in conversation with survival, maintenance, ecology, and the people who have to live with the design.',titles:['The High Frontier','A City on Mars','Packing for Mars','Space Settlements','Aurora','Red Mars','Record of a Spaceborn Few','2312'],project:'Make a habitat dependency map: air, water, heat, repair, food, privacy, and a way to recover from mistakes.'},
 {id:'robots',name:'Machines with minds',caption:'Mechanisms → control → agency',desc:'Understand the machinery and computation, then use fiction to explore autonomy, identity, and responsibility. A powerful mind is not a substitute for a reliable joint.',titles:['Making Things Move','Code','Modern Robotics','Probabilistic Robotics','All Systems Red','A Closed and Common Orbit','Ancillary Justice','Exhalation'],project:'Separate sensing, planning, actuation, and verification in a single robotic task.'},
 {id:'builders',name:'How ambitious things get built',caption:'People. Programs. Failure. Judgment.',desc:'Get close to the teams behind difficult hardware. Read achievement alongside failure, and notice how information, incentives, and tests shape what happens.',titles:['Skunk Works','Digital Apollo','Failure Is Not an Option','To Engineer Is Human','Normal Accidents','The Checklist Manifesto','The Soul of a New Machine','The Right Stuff'],project:'Write a one-page decision memo for a small project: evidence, alternatives, risks, and the next test.'},
 {id:'culture',name:'A doorway into the Culture',caption:'Iain M. Banks, without a homework contract',desc:'An editorial route through machine intelligence, enormous habitats, abundance, power, and intervention. Mostly standalone stories; this is a suggested path, not a mandatory sequence.',titles:['The Player of Games','Consider Phlebas','Excession','Look to Windward','Use of Weapons','The State of the Art','Inversions','Matter','Surface Detail','The Hydrogen Sonata'],project:'Ask what the technology has solved—and which human or political problems remain.'},
 {id:'oceans',name:'Strange environments, familiar questions',caption:'Oceans. Alien worlds. Limits of knowledge.',desc:'For the part of you drawn to machines beyond easy reach. These stories reward curiosity about environments, ecology, contact, and the limits of your own assumptions.',titles:['The Deep','Seven-Tenths','The Sea Around Us','Solaris','The Mountain in the Sea','Startide Rising','A Darkling Sea','Dragon’s Egg'],project:'List the environmental assumptions a terrestrial robot would lose underwater or on another world.'}
];
function findBook(title){const n=norm(title);return books.find(b=>norm(b.title)===n)||books.find(b=>norm(b.title).startsWith(n))||books.find(b=>norm(b.title).includes(n));}
function pathBooks(p){return p.titles.map(findBook).filter(Boolean).filter((b,i,a)=>a.findIndex(x=>x.id===b.id)===i);}
function glyph(seed=0){const style='fill="none" stroke="currentColor" stroke-width="1.15"';const forms=[
 `<g ${style}><circle cx="100" cy="75" r="45"/><ellipse cx="100" cy="75" rx="83" ry="22" transform="rotate(-28 100 75)"/><path d="M100 20v110M45 75h110" stroke-dasharray="2 5"/><circle cx="163" cy="44" r="4" fill="currentColor"/></g>`,
 `<g ${style}><path d="M25 115 100 25l75 90zM25 115l75-35 75 35M100 25v105M63 70l75 0M44 93h112"/><circle cx="100" cy="80" r="25"/><path d="M15 135h170M27 140v-10M173 140v-10"/></g>`,
 `<g ${style}><circle cx="90" cy="75" r="44"/><circle cx="90" cy="75" r="29"/><circle cx="90" cy="75" r="8"/><path d="M90 19v24m0 64v24M34 75h24m64 0h24M50 35l17 17m46 46 17 17M50 115l17-17m46-46 17-17"/><path d="M145 38h25v74h-25M159 45v60"/></g>`,
 `<g ${style}><path d="M20 125V35h160v90zM20 80h160M65 35v90M135 35v90M20 35l45 45-45 45M180 35l-45 45 45 45M65 35l70 90m0-90-70 90"/><path d="M15 143h170M15 138v10m170-10v10"/></g>`,
 `<g ${style}><path d="M10 50q30-45 60 0t60 0 60 0M10 70q30-45 60 0t60 0 60 0M10 90q30-45 60 0t60 0 60 0M10 110q30-45 60 0t60 0 60 0"/><circle cx="100" cy="75" r="57"/></g>`,
 `<g ${style}><path d="M20 125h165M30 135V15M30 125Q60 120 80 85T170 25M30 125 170 25"/><path d="M80 125V85h55M135 125V40" stroke-dasharray="3 5"/><circle cx="80" cy="85" r="4" fill="currentColor"/></g>`];return `<svg viewBox="0 0 200 150" aria-hidden="true">${forms[seed%forms.length]}</svg>`;}
function palette(b){const n=parseInt(b.id.slice(1),10)+(b.kind==='fiction'?3:0);return palettes[n%palettes.length];}
function cover(b){const p=palette(b),n=parseInt(b.id.slice(1),10);return `<div class="cover" style="--cover-bg:${p[0]};--cover-fg:${p[1]}"><div class="cover-top"><span>${b.kind==='fiction'?'IMAGINED WORLDS':'PHYSICAL FOUNDATIONS'}</span><span>${String(n).padStart(3,'0')}</span></div><h3 class="${b.title.length>34?'long-title':''}">${esc(b.title)}</h3><div class="cover-art">${glyph(n)}</div><div class="cover-author">${esc(b.author)}</div><span class="collection-mark">READING ATLAS</span></div>`;}
function card(b){const r=records[b.id]||{},saved=!!r.status;return `<article class="book-card" data-book-id="${b.id}"><button class="cover-button" data-open="${b.id}" aria-label="Explore ${esc(b.title)}">${cover(b)}</button><div class="book-info"><div class="meta">${esc(b.category)}${b.year?` · ${b.year}`:''}</div><h3><a href="#book/${b.id}" data-open="${b.id}">${esc(b.title)}</a></h3><div class="author">${esc(b.author)}</div><p class="why-short">${esc(b.why)}</p>${r.status?`<span class="book-status">${statusNames[r.status]}</span>`:''}</div><div class="card-footer"><span class="level" title="${levels[b.difficulty]} — editorial estimate"><span class="level-dots" aria-hidden="true">${[1,2,3,4,5].map(i=>`<i class="${i<=b.difficulty?'on':''}"></i>`).join('')}</span>${esc(b.stage)}</span><button class="save-btn ${saved?'saved':''}" data-save="${b.id}" aria-label="${saved?'Remove from shelf:':'Save to shelf:'} ${esc(b.title)}" aria-pressed="${saved}">${saved?'✓ Saved':'+ Save'}</button></div></article>`;}
function cards(bs,cl=''){return `<div class="cards ${cl}">${bs.map(card).join('')}</div>`;}
function pathCard(p,i){return `<a href="#path/${p.id}" class="path-card"><span class="num">ROUTE ${String(i+1).padStart(2,'0')}</span><h3>${esc(p.name)}</h3><p>${esc(p.caption)}</p><span class="path-bottom">${pathBooks(p).length} BOOKS · A PATH, NOT A DEADLINE <span class="arrow">↗</span></span></a>`;}
function home(){return basecamp();}
function terafabURL(){return 'https://content.spacex.com/cms-assets/FINAL_Documents%20and%20Updates/SpaceX%20-%20EU%20Prospectus%20%28Approved%20by%20Bafin%29%20-%20June%205%2C%202026.pdf';}
function categoryOptions(){return [...new Set(books.filter(b=>filters.kind==='all'||b.kind===filters.kind).map(b=>b.category))].sort().map(c=>`<option value="${esc(c)}" ${filters.category===c?'selected':''}>${esc(c)}</option>`).join('');}
function catalog(){return `<section class="page-head"><span class="eyebrow">THE COMPLETE COLLECTION / ${books.length} DISTINCT BOOKS</span><h1>Your next good question<br>might be on this shelf.</h1><p class="lead">Search by title, author, or idea. Start accessible, follow your curiosity, and keep the technical references for when you need them.</p></section><section class="catalog"><div class="filter-panel"><div class="filter-top"><div class="segmented" aria-label="Book type">${[['all','All books',books.length],['nonfiction','Nonfiction',books.filter(b=>b.kind==='nonfiction').length],['fiction','Fiction',books.filter(b=>b.kind==='fiction').length]].map(([v,l,c])=>`<button data-kind="${v}" class="${filters.kind===v?'active':''}" aria-pressed="${filters.kind===v}">${l}<span>${c}</span></button>`).join('')}</div><label class="search-wrap"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></svg><input id="book-search" type="search" value="${esc(filters.q)}" placeholder="Title, author, or an idea…" aria-label="Search all books"></label></div><div class="filter-bottom"><label>Knowledge field<select id="domain"><option value="all">All connected fields</option>${atlasDomains.map(d=>`<option value="${d.id}" ${filters.domain===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><label>Subject<select id="category"><option value="all">Every subject</option>${categoryOptions()}</select></label><label>Where you are<select id="stage"><option value="all">Any reading stage</option>${['Start here','Build foundations','Go deeper','Reference'].map(c=>`<option ${filters.stage===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Reading demand<select id="difficulty"><option value="all">Any level</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${filters.difficulty==n?'selected':''}>${n} · ${levels[n]}</option>`).join('')}</select></label><label>Arrange by<select id="sort">${[['curated','Curated order'],['title','Title A–Z'],['author','Author A–Z'],['year','Publication year'],['easy','Easier first']].map(([v,l])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="clear-btn" data-action="clear-filters">Reset filters</button></div></div><div class="results-line"><span id="result-count" role="status" aria-live="polite"></span><div class="view-toggle" aria-label="Display style"><button data-view="grid" class="${filters.view==='grid'?'active':''}" aria-label="Grid view" aria-pressed="${filters.view==='grid'}">▦</button><button data-view="list" class="${filters.view==='list'?'active':''}" aria-label="List view" aria-pressed="${filters.view==='list'}">☷</button></div></div><div id="catalog-results"></div><div class="load-more" id="load-more-wrap"></div><p class="note" style="margin-top:35px">Reading demand is an editorial estimate: technical prerequisites for nonfiction, narrative density for fiction. Original publication years where verified; source pages may show later editions. Cover designs are original atlas illustrations, not publisher jackets.</p></section>`;}
function filteredBooks(){const q=norm(filters.q.trim());let list=books.filter(b=>(filters.domain==='all'||domainById(filters.domain)?.bookIds.includes(b.id))&&(filters.kind==='all'||b.kind===filters.kind)&&(filters.category==='all'||b.category===filters.category)&&(filters.stage==='all'||b.stage===filters.stage)&&(filters.difficulty==='all'||b.difficulty===Number(filters.difficulty))&&(!q||norm([b.title,b.author,b.why,b.category,...b.tags].join(' ')).includes(q)));if(filters.sort==='curated')list.sort((a,b)=>(Number(a.id.slice(1))*2+(a.kind==='fiction'?1:0))-(Number(b.id.slice(1))*2+(b.kind==='fiction'?1:0)));if(filters.sort==='title'||filters.sort==='author')list.sort((a,b)=>a[filters.sort].localeCompare(b[filters.sort]));if(filters.sort==='year')list.sort((a,b)=>(a.year??9999)-(b.year??9999));if(filters.sort==='easy')list.sort((a,b)=>a.difficulty-b.difficulty);return list;}
function updateResults(){if(!$('#catalog-results'))return;const list=filteredBooks();$('#result-count').textContent=`${list.length} ${list.length===1?'book':'books'} found${list.length>shown?` · showing ${shown}`:''}`;$('#catalog-results').innerHTML=list.length?cards(list.slice(0,shown),filters.view==='list'?'list':''):`<div class="empty"><span class="eyebrow">A DIFFERENT WAY IN</span><h2>No books match this combination.</h2><p>Try a broader idea, another subject, or clear the filters to return to all ${books.length} books.</p><button class="btn light small" data-action="clear-filters">Clear filters →</button></div>`;$('#load-more-wrap').innerHTML=list.length>shown?`<button class="btn light" data-action="load-more">Show ${Math.min(24,list.length-shown)} more <span>↓</span></button>`:'';}
function routesPage(){return `<section class="page-head"><span class="eyebrow">READING ROUTES / ${paths.length} WAYS INTO THE ATLAS</span><h1>Follow the question.<br><i>See where it takes you.</i></h1><p class="lead">A reading route is a conversation between books. Move between technical foundations, lived engineering experience, and imagined futures. Skip around. Change direction. Come back later.</p></section><section class="section" style="padding-top:20px"><div class="path-grid">${paths.map(pathCard).join('')}</div></section>`;}
function routePage(id){const p=paths.find(x=>x.id===id);if(!p)return notFound();const bs=pathBooks(p);return `<section class="page-head"><a class="text-link" href="#paths">← All reading routes</a></section><section class="section path-detail" style="padding-top:10px"><div class="path-intro"><span class="eyebrow">${esc(p.caption)}</span><h2>${esc(p.name)}</h2><p>${esc(p.desc)}</p><button class="btn small" data-save-route="${p.id}">Save this route <span>+</span></button><h3 style="font-size:24px;margin:35px 0 14px">Bring it back to the bench.</h3><p>${esc(p.project)}</p><p class="note">This sequence is editorial guidance, not a course requirement. Check each book’s stage and reading demand before choosing the next one.</p></div><div>${bs.map((b,i)=>`<article class="reading-step"><span class="step-num">${String(i+1).padStart(2,'0')}</span><div><div class="author-line">${esc(b.kind)} · ${esc(b.stage)}</div><h3>${esc(b.title)}</h3><p>${esc(b.author)}</p><p>${esc(b.why)}</p><div class="step-actions"><button class="btn small light" data-open="${b.id}">Explore the book ↗</button><button class="save-btn ${records[b.id]?.status?'saved':''}" data-save="${b.id}">${records[b.id]?.status?'✓ Saved':'+ Save to shelf'}</button></div></div></article>`).join('')}</div></section>`;}
function banksPage(){const p=paths.find(x=>x.id==='culture');return `<section class="page-head"><span class="eyebrow">IAIN M. BANKS / A VERY GOOD QUESTION</span><h1>Meet the Culture.<br>Expand the horizon.</h1><p class="lead">The draw is the combination: intelligent machines, enormous habitats, freedom from many material constraints, and serious questions about what a civilization should do with that power.</p></section><section class="section editorial-grid" style="padding-top:20px"><div class="panel"><span class="eyebrow">WHERE I’D START</span><h2>The Player of Games</h2><p>My first pick for a readable doorway into the Culture’s values and contradictions. Follow it with <em>Consider Phlebas</em> for another perspective, then <em>Excession</em> when you want more of the machine-intelligence and civilization-scale side.</p><button class="btn small" data-open="${findBook('The Player of Games')?.id}">Meet your first Banks book ↗</button></div><div class="panel"><span class="eyebrow">WHAT TO BRING WITH YOU</span><h2>Curiosity—and a second shelf.</h2><p>The Culture is a fictional thought experiment, not an aerospace roadmap. Its advanced capabilities include speculative physics. Pair it with <em>Thinking in Systems</em>, <em>The High Frontier</em>, and <em>A City on Mars</em> to keep asking what is physical, institutional, or assumed away.</p><p class="note">Banks can be dark, violent, and sexually explicit. These are adult recommendations. The site’s suggested order is editorial, not a rule from the author.</p></div></section><div class="callout-band"><span class="eyebrow">THE READING QUESTION</span><p>After machines make abundance possible, what still makes a life—or a civilization—good?</p></div><section class="section"><div class="section-head"><div><span class="eyebrow">NINE NOVELS + ONE COLLECTION</span><h2>A shelf of possible worlds.</h2></div><a href="#path/culture" class="text-link">Follow the suggested route ↗</a></div><p class="note" style="margin-bottom:30px"><em>The State of the Art</em> is a story collection, not a tenth Culture novel. The books are largely standalone, with connections and callbacks. Publication order is another perfectly reasonable route.</p>${cards(pathBooks(p))}</section>`;}
function shelfPage(){const all=books.filter(b=>records[b.id]?.status);const list=all.filter(b=>shelfFilter==='all'||records[b.id].status===shelfFilter);const counts={want:all.filter(b=>records[b.id].status==='want').length,reading:all.filter(b=>records[b.id].status==='reading').length,finished:all.filter(b=>records[b.id].status==='finished').length};return `<section class="page-head"><span class="eyebrow">YOUR READING SHELF / ROOM TO GROW</span><h1>A few books.<br>A longer horizon.</h1><p class="lead">Save what interests you. Keep a question beside it. Your shelf and notes stay in this browser; export a backup to carry them to another device.</p><div class="shelf-stats"><div><strong>${counts.want}</strong><span>Want to read</span></div><div><strong>${counts.reading}</strong><span>Reading</span></div><div><strong>${counts.finished}</strong><span>Finished</span></div></div><div class="shelf-actions"><button data-action="export-shelf">Export shelf & notes ↓</button><button data-action="import-shelf">Import a backup ↑</button><button data-action="export-catalog">Download all ${books.length} as CSV ↓</button></div></section><section class="section" style="padding-top:5px"><div class="segmented shelf-tabs" aria-label="Shelf status">${[['all','All saved'],['want','Want to read'],['reading','Reading'],['finished','Finished']].map(([v,l])=>`<button data-shelf-filter="${v}" class="${shelfFilter===v?'active':''}" aria-pressed="${shelfFilter===v}">${l}</button>`).join('')}</div>${list.length?cards(list):`<div class="empty"><span class="eyebrow">NO RUSH. NO STREAK TO LOSE.</span><h2>${all.length?'Nothing in this part of your shelf yet.':'Your shelf starts with one good book.'}</h2><p>Save a book, then open its detail panel to mark it reading or finished and keep your own notes.</p><a href="#path/first" class="btn light">Find your first book ↗</a></div>`}</section>`;}
function aboutPage(){return `<section class="page-head"><span class="eyebrow">ABOUT / CURATION & SOURCES</span><h1>Less scrolling.<br>More to discover.</h1><p class="lead">A free reading and learning atlas for curious people: future engineers, hands-on builders, science-fiction readers, and anyone interested in what a more capable civilization could become.</p></section><section class="section about-body"><h2>Why these ${books.length}?</h2><p>The nonfiction shelf mixes approachable explanations, builder histories, manufacturing, mathematical foundations, systems thinking, and clearly marked technical references. The fiction shelf explores machines, habitats, ecology, civilizations, power, and human lives inside technological change. Choose what interests you; this is a library of possibilities, not a completion challenge.</p><p>The core catalog contains ${books.filter(b=>b.kind==='nonfiction').length} distinct nonfiction selections and ${books.filter(b=>b.kind==='fiction').length} distinct fiction selections. A collection counts as one book; a novel is not duplicated through an omnibus. Narrative teaching books such as <em>The Goal</em> are shelved with nonfiction for their management purpose, with their fictional framing disclosed. Fiction includes adult novels, novellas, and story collections. The expanded subject map connects mathematics, chemistry, biology, longevity, philosophy, defense history, and engineering. A book can appear in multiple subject shelves, but is counted only once in the catalog.</p><h2>How the sources work</h2><p>Each book has a bibliographic source link, favoring author, publisher, institutional, or open-textbook pages. These help verify identity and editions. Relevance notes, questions, reading routes, difficulty levels, and order are original editorial judgments; a source link does not mean the author endorses this atlas.</p><p>Publication years refer to original publication where established. A publisher may show a later edition or reissue. This is a curated guide, not a claim that every book was read cover to cover while making the site. Prices, stock, and library availability are not promised. Check a source, your local library, or a bookseller for an edition that suits you.</p><h2>Read to your current level</h2><p>“Start here” means a reasonable entry point, not effortless reading. “Reference” means a book to consult or work toward with prerequisites. Demand scores are editorial estimates, not standardized assessments. For fiction they describe narrative density; for technical nonfiction they also reflect mathematical preparation. An advanced book on a shelf is a direction, not a deadline.</p><h2>Your shelf and notes stay in your browser</h2><p>No signup is required. The site stores reading status, book notes, exploration marks, and field notes in this browser’s local storage. These records are not sent to a database or shared with other visitors. Different people visiting this site start with their own empty shelves. Data does not synchronize between devices.</p><p>Clearing site data, switching browsers, or losing access to this browser can remove access to your records. Your shelf has a JSON backup export for books and notes; Your field notes has a separate journey backup. Imports merge recognized records and replace matching entries. Export all ${books.length} as CSV downloads the complete catalog, including source links. Backup files contain the notes you entered, so share them only if you intend to share that content.</p><p>If browser storage is unavailable, changes can remain only for the current session. The site has no added analytics, advertising, affiliate links, or purchase flow. The hosting provider may maintain ordinary request logs under its own policies. External source links take you to other sites with their own privacy practices.</p><h2>A note on the visuals</h2><p>The book covers are original typographic illustrations, not reproductions of published jackets. Diagrams are educational schematics, not engineering specifications. The orbital shipyard illustration is AI-generated speculative concept art; it does not depict an existing facility.</p><p class="note">Editorial research snapshot: October 2026. New editions, institutional pages, company plans, and links can change.</p></section>`;}
function notFound(){return `<section class="section empty"><h1>This page isn’t in the atlas.</h1><p>Return to the collection to find your next book.</p><a href="#library" class="btn">Explore all ${books.length} ↗</a></section>`;}
function render(){
 const parts=location.hash.slice(1).split('/');page=parts[0]||'home';
 if(page==='book'){if(!$('#main').querySelector('.horizon-hero,.catalog,.page-head'))$('#main').innerHTML=basecamp();openBook(parts[1]);return;}
 if($('#book-dialog').open)$('#book-dialog').close();
 if(page==='library'){const field=domainById(parts[1])?parts[1]:'all';if(field!==filters.domain){filters={...filters,domain:field,category:'all',kind:'all',q:'',stage:'all',difficulty:'all'};shown=24;}}
 const extra=page==='atlas'?atlasPage():page==='domain'?domainPage(parts[1]):renderExtra(page,parts[1]);
 const html=extra??({library:catalog,paths:routesPage,banks:banksPage,shelf:shelfPage,about:()=>aboutPage()+v2About()}[page]||(()=>page==='path'?routePage(parts[1]):notFound()))();
 $('#main').innerHTML=html;
 const labels={home:'Basecamp',journey:'Your journey',lesson:'Learning bridge',frontiers:'Five frontiers',frontier:'Frontier dossier',ideas:'What is worth building?',night:'Night reading',workbench:'Interactive workbench',projects:'Small builds',journal:'Your field notes',library:'The '+books.length+' books',atlas:'The knowledge map',domain:domainById(parts[1])?.name,paths:'Reading routes',path:paths.find(x=>x.id===parts[1])?.name,banks:'Why Iain M. Banks?',shelf:'Your reading shelf',about:'Curation & sources'};
 document.title=(labels[page]||'Reading Atlas')+' · Ditch the Scroll';
 const navPage=({domain:'atlas',path:'library',paths:'library',banks:'night',lesson:'journey',projects:'journey',workbench:'journey',journal:'journey',frontier:'frontiers'})[page]||page;
 document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===navPage)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(page==='library')updateResults();updateCount();window.scrollTo(0,0);
}
function updateCount(){$('#shelf-count').textContent=Object.values(records).filter(r=>r.status).length;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,records}));return true;}catch{toast('Browser storage unavailable. Export a backup before leaving.');return false;}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200);}
function refreshButtons(){document.querySelectorAll('[data-save]').forEach(btn=>{const b=index.get(btn.dataset.save);const saved=!!records[b?.id]?.status;btn.textContent=saved?'✓ Saved':'+ Save';btn.classList.toggle('saved',saved);btn.setAttribute('aria-pressed',String(saved));btn.setAttribute('aria-label',`${saved?'Remove from shelf:':'Save to shelf:'} ${b?.title||''}`);});document.querySelectorAll('.book-card').forEach(el=>{const status=records[el.dataset.bookId]?.status;let badge=el.querySelector('.book-status');if(status){if(!badge){badge=document.createElement('span');badge.className='book-status';el.querySelector('.book-info').append(badge);}badge.textContent=statusNames[status];}else if(badge)badge.remove();});updateCount();}
function saveBook(id){const r=records[id]||{};if(r.status){r.status='';toast('Removed from shelf. Your notes are retained.');}else{r.status='want';toast('Added to your reading shelf.');}records[id]=r;persist();if(page==='shelf')render();else refreshButtons();}
function openBook(id){const b=index.get(id);if(!b){toast('That book could not be found.');return;}currentBook=b;lastFocus=document.activeElement;const r=records[id]||{};$('#book-dialog').innerHTML=`<button class="dialog-close" data-action="close-dialog" aria-label="Close book details">×</button><div class="dialog-layout"><div class="dialog-cover">${cover(b)}<a class="source-button" href="${esc(b.source.url)}" target="_blank" rel="noopener">Author / publisher source ↗</a></div><div class="dialog-body"><span class="eyebrow">${esc(b.kind)} · ${esc(b.category)}</span><h2 id="dialog-title">${esc(b.title)}</h2><p class="author">${esc(b.author)}${b.year?` · First published ${b.year}`:''}</p><span class="badge">${esc(b.stage)} · Demand ${b.difficulty}/5</span><h3>Why it belongs on your shelf</h3><p>${esc(b.why)}</p><h3>Carry this question with you</h3><p class="question">${esc(b.question)}</p><p class="caveat">${esc(b.caveat)}</p><div class="dialog-tags">${b.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><label for="book-status">Your reading status</label><select id="book-status"><option value="">Not on my shelf</option>${Object.entries(statusNames).map(([v,l])=>`<option value="${v}" ${r.status===v?'selected':''}>${l}</option>`).join('')}</select><label for="book-notes">Your notes & questions</label><textarea id="book-notes" maxlength="12000" placeholder="What did this make you want to understand, test, or build?">${esc(r.notes||'')}</textarea><p class="local-note">Saved automatically on this device. Export a backup from Your shelf.</p><p class="dialog-source">Bibliographic source: <a href="${esc(b.source.url)}" target="_blank" rel="noopener">${esc(b.source.label)} ↗</a><br>Reading fit and difficulty are editorial judgments. Source editions may differ.</p></div></div>`;if(!$('#book-dialog').open)$('#book-dialog').showModal();}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCatalog(){const cols=['title','author','kind','year','category','stage','difficulty','why','question','caveat','source'];const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const rows=books.map(b=>cols.map(k=>quote(k==='source'?b.source.url:b[k])).join(','));download('\ufeff'+cols.join(',')+'\r\n'+rows.join('\r\n'),'text/csv;charset=utf-8',`builders-reading-atlas-${books.length}-books.csv`);toast('Complete catalog downloaded.');}
function validRecords(obj){const clean={};if(!obj||typeof obj!=='object'||Array.isArray(obj))throw Error('Invalid records');for(const [id,r]of Object.entries(obj)){if(!index.has(id)||!r||typeof r!=='object')continue;const status=['want','reading','finished',''].includes(r.status)?r.status:'';const notes=typeof r.notes==='string'?r.notes.slice(0,12000):'';clean[id]={status,notes};}return clean;}
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.classList.contains('skip')){e.preventDefault();$('#main').focus();return;}if(t.dataset.open){e.preventDefault();openBook(t.dataset.open);return;}if(t.dataset.save){saveBook(t.dataset.save);return;}if(t.dataset.kind){filters.kind=t.dataset.kind;filters.category='all';shown=24;$('#main').innerHTML=catalog();updateResults();return;}if(t.dataset.view){filters.view=t.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===filters.view);b.setAttribute('aria-pressed',String(b.dataset.view===filters.view));});updateResults();return;}if(t.dataset.shelfFilter){shelfFilter=t.dataset.shelfFilter;render();return;}if(t.dataset.saveRoute){const p=paths.find(x=>x.id===t.dataset.saveRoute);pathBooks(p).forEach(b=>{if(!records[b.id]?.status)records[b.id]={...records[b.id],status:'want'};});const routeStored=persist();refreshButtons();if(routeStored)toast('Reading route added to your shelf.');return;}switch(t.dataset.action){case'clear-filters':filters={domain:'all',kind:'all',category:'all',stage:'all',difficulty:'all',q:'',sort:'curated',view:filters.view};shown=24;if(location.hash!=='#library')location.hash='library';else{$('#main').innerHTML=catalog();updateResults();}break;case'load-more':shown+=24;updateResults();break;case'close-dialog':$('#book-dialog').close();break;case'export-shelf':download(JSON.stringify({version:1,exported:new Date().toISOString(),records},null,2),'application/json','builders-reading-atlas-backup.json');toast('Your shelf and notes have been exported.');break;case'import-shelf':$('#import-file').click();break;case'export-catalog':exportCatalog();break;}});
document.addEventListener('input',e=>{if(e.target.id==='book-search'){filters.q=e.target.value;shown=24;updateResults();}if(e.target.id==='book-notes'&&currentBook){records[currentBook.id]={...records[currentBook.id],notes:e.target.value};persist();}});
document.addEventListener('change',e=>{if(e.target.id==='domain'){location.hash=e.target.value==='all'?'library':'library/'+e.target.value;return;}if(['category','stage','difficulty','sort'].includes(e.target.id)){filters[e.target.id]=e.target.value;shown=24;updateResults();}if(e.target.id==='book-status'&&currentBook){records[currentBook.id]={...records[currentBook.id],status:e.target.value};const statusStored=persist();refreshButtons();if(statusStored)toast(e.target.value?`Marked ${statusNames[e.target.value].toLowerCase()}.`:'Removed from shelf.');}});
$('#book-dialog').addEventListener('click',e=>{if(e.target===$('#book-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#book-dialog').addEventListener('close',()=>{currentBook=null;if(page==='book'){location.hash='home';return;}if(page==='shelf')render();if(lastFocus?.isConnected)lastFocus.focus();});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>40000000)throw Error('Large file');const data=JSON.parse(await f.text());if(data.version!==1)throw Error('Version');const imported=validRecords(data.records);if(!Object.keys(imported).length)throw Error('No records');records={...records,...imported};const importStored=persist();render();if(importStored)toast(`Imported ${Object.keys(imported).length} book records.`);}catch{toast('Could not import. Choose a Reading Atlas JSON backup.');}e.target.value='';});
window.addEventListener('hashchange',render);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('#book-dialog').open){e.preventDefault();if(page!=='library'){location.hash='library';setTimeout(()=>$('#book-search')?.focus(),30);}else $('#book-search')?.focus();}});
async function init(){
 try{
  const files=['books.json','learning.json','philosophy.json','frontiers.json','domains.json'];
  const data=await Promise.all(files.map(async f=>{const r=await fetch(f);if(!r.ok)throw Error('Could not load '+f);return r.json();}));
  [books,learning,philosophy,frontierData,atlasDomains]=data;
  if(!Array.isArray(books)||!books.length||new Set(books.map(b=>b.id)).size!==books.length)throw Error('Catalog invalid');
  index=new Map(books.map(b=>[b.id,b]));
  try{const saved=JSON.parse(localStorage.getItem(KEY)||'{"records":{}}');records=validRecords(saved.records);}catch{records={};}
  expandRoutes();loadJourney();render();
 }catch{$('#main').innerHTML='<section class="section empty"><h1>The atlas couldn’t load.</h1><p>Please reload the page. Your shelf and notes remain in this browser.</p><button class="btn" onclick="location.reload()">Reload the atlas ↻</button></section>';}
}
init();
